$attendanceStatusCounts = array_fill_keys(['PRESENT', 'ABSENT', 'HALF_DAY', 'WORK_FROM_HOME', 'ON_LEAVE'], 0);
foreach ($attendanceRows as $row) {
    if ((string) ($row['attendance_date'] ?? '') === $selectedDate && isset($attendanceStatusCounts[(string) ($row['attendance_status'] ?? '')])) {
        $attendanceStatusCounts[(string) $row['attendance_status']]++;
    }
}
