$attendanceDialogClass = 'flex max-h-[calc(100dvh-2rem)] w-[calc(100vw-2rem)] max-w-3xl flex-col overflow-hidden rounded-lg border bg-popover shadow-lg';
$employeeOptions = static function (array $employees, string $selected = ''): void {
    foreach ($employees as $employee) {
